$d=".tmp\gate-8b00af0"; New-Item -ItemType Directory -Force $d | Out-Null; $s="$d\summary.txt"
"HEAD $(git rev-parse HEAD) clean=[$(git status --porcelain)] start $(Get-Date -Format o)" | Out-File -Encoding utf8 $s
function g($n,$cmd){ cmd /c "$cmd > $d\$n.log 2>&1"; "$n exit=$LASTEXITCODE" | Out-File -Append -Encoding utf8 $s }
g install "pnpm install --frozen-lockfile"; g build "pnpm build"; g typecheck "pnpm typecheck"; g lint "pnpm lint"; g vitest "pnpm exec vitest run"; g smoke "pnpm smoke:p0-native"; g s7 "node scripts/e2e-s7-integrated.mjs"
cmd /c "`"C:\Program Files\Git\bin\bash.exe`" scripts/audit-inventory.sh . > $d\audit-inventory.log 2>&1"; "audit-inventory.sh exit=$LASTEXITCODE (inventory only, not a security audit)" | Out-File -Append -Encoding utf8 $s
rg -n -i "(api[_-]?key|appid|secret|token|password)\s*[:=]\s*['\x22][A-Za-z0-9]{16,}" server shared src scripts/r1-5-7-policy-display.mjs > "$d\self-scan.log" 2>&1; "self-scan rg exit=$LASTEXITCODE (1 = no match)" | Out-File -Append -Encoding utf8 $s
cmd /c "node --import tsx/esm --experimental-loader ./scripts/tsx-alias-loader.mjs ./scripts/r1-5-4-nalgae-replay.ts > $d\nalgae-replay.json 2> $d\nalgae-replay.err"; "nalgae-replay script exit=$LASTEXITCODE" | Out-File -Append -Encoding utf8 $s
rg -n -i "(PHPSESSID|__jsluid_s|ASP\.NET_SessionId|csrf[-_]?token)\S{0,12}([=:]|\x22 content=)\s*[\x22]?[A-Za-z0-9]{6,}" docs/evidence/r1-5-4-eligibility-2026-10-12 docs/evidence/r1-5-4-nalgae-source-record-2026-10-12.md docs/evidence/r1-5-4-nalgae-replay-trial-2026-10-12.md docs/evidence/r1-5-4-replay-method-2026-10-12.md docs/evidence/r1-5-4-eligibility-round2-2026-10-12.md > "$d\evidence-scan.log" 2>&1; "evidence-scan rg (round docs/evidence + raw headers: session cookie/csrf values) exit=$LASTEXITCODE (1 = no match)" | Out-File -Append -Encoding utf8 $s
rg -n -i "(api[_-]?key|appid|secret|token|password|authorization)\s*[:=]\s*[\x27\x22]?[A-Za-z0-9]{16,}" docs/evidence/r1-5-4-eligibility-2026-10-12 docs/evidence/r1-5-4-nalgae-source-record-2026-10-12.md docs/evidence/r1-5-4-nalgae-replay-trial-2026-10-12.md > "$d\evidence-scan-tokens.log" 2>&1; "evidence-scan rg (round docs/evidence: key/token values) exit=$LASTEXITCODE (1 = no match)" | Out-File -Append -Encoding utf8 $s
"end $(Get-Date -Format o) clean=[$(git status --porcelain)]" | Out-File -Append -Encoding utf8 $s
